/* New York State + New York City personal income tax engine, tax year 2026.
 *
 * A JavaScript port of the relevant formulas in PolicyEngine US
 * (github.com/PolicyEngine/policyengine-us), limited to households whose only
 * income is wages and who take the standard deduction. Parameter values come
 * from PolicyEngine's own parameter files (params-2026.json, generated by
 * scripts/dump_params.py). Every formula below names the PolicyEngine variable
 * it mirrors. Tested against PolicyEngine itself: see scripts/check_engine.py.
 */
(function (root) {
  "use strict";

  const INF = Infinity;
  const num = (t) => (t === "inf" ? INF : t === "-inf" ? -INF : t);

  // MarginalRateTaxScale.calc
  function marginal(scale, x) {
    const t = scale.thresholds.map(num), r = scale.rates;
    let tax = 0;
    for (let i = 0; i < t.length; i++) {
      const lo = t[i], hi = i + 1 < t.length ? t[i + 1] : INF;
      if (x > lo) tax += r[i] * (Math.min(x, hi) - lo);
    }
    return tax;
  }

  // SingleAmountTaxScale.calc. A leading "inf" in the dumped JSON is -inf.
  // right=false: bracket i when t[i] <= x < t[i+1]; right=true: t[i] < x <= t[i+1].
  function single(scale, x, right) {
    const t = scale.thresholds.map((v, i) => (i === 0 && v === "inf" ? -INF : num(v)));
    let idx = -1;
    for (let i = 0; i < t.length; i++) {
      if (right ? x > t[i] : x >= t[i]) idx = i;
    }
    return idx < 0 ? 0 : scale.amounts[idx];
  }

  const STATUS_KEY = { SINGLE: "single", JOINT: "joint", HEAD_OF_HOUSEHOLD: "head_of_household" };

  /* Household:
   *   married: boolean (married couples file jointly)
   *   wages: total wages for the tax unit
   *   kidsUnder4, kids4to16, kids17to18: dependent children by age
   * Parameters: the params-2026.json object, optionally edited by levers, plus
   *   P.extra (levers PolicyEngine does not model as parameters; see below).
   */
  function compute(h, P) {
    const ny = P.ny, nyc = P.nyc, fed = P.eitc, ex = P.extra || {};
    const kids = (h.kidsUnder4 || 0) + (h.kids4to16 || 0) + (h.kids17to18 || 0);
    const status = h.married ? "JOINT" : kids > 0 ? "HEAD_OF_HOUSEHOLD" : "SINGLE";
    const sk = STATUS_KEY[status];
    const people = (h.married ? 2 : 1) + kids; // exemptions_count
    const wages = Math.max(0, h.wages || 0);
    const agi = wages; // adjusted_gross_income, ny_agi, ny_recomputed_federal_agi

    // ---- Federal EITC (eitc), needed for the state and city matches
    const eitcKids = Math.min(kids, 3);
    const eMax = single(fed.max, eitcKids, false);
    const phasedIn = Math.min(eMax, wages * single(fed.phase_in_rate, eitcKids, false));
    const start = single(fed.phase_out.start, eitcKids, false) +
      (h.married ? single(fed.phase_out.joint_bonus, eitcKids, false) : 0);
    const reduction = single(fed.phase_out.rate, eitcKids, false) * Math.max(0, Math.max(wages, agi) - start);
    // Childless filers must be 25 to 64; adults here are assumed to be.
    const fedEitc = Math.min(phasedIn, Math.max(0, eMax - reduction));

    // Lever not in PolicyEngine: the Working Families Tax Credit (S2082), fully
    // phased in. It replaces the Empire State Child Credit, ends the state EITC
    // and the dependent exemption for filers with children through age 17, and
    // pays one credit per child. All children here are 17 or younger.
    const wftc = ex.wftc && kids > 0 ? ex.wftc : null;

    // ---- New York State
    // ny_taxable_income = ny_agi - standard deduction - $1,000 per dependent
    const exemptKids = wftc ? 0 : kids;
    const nyTI = Math.max(0, agi - ny.deductions.standard.amount[status] - ny.exemptions.dependent * exemptKids);
    const mainScale = ny.main[sk];
    const nyMain = marginal(mainScale, nyTI); // ny_main_income_tax

    // ny_supplemental_tax (the "tax benefit recapture")
    const s = ny.supplemental;
    const th = mainScale.thresholds.map(num);
    let prevIdx = 0;
    for (let i = 0; i < th.length; i++) if (th[i] <= nyTI) prevIdx = i;
    const prevThreshold = th[prevIdx];
    const finite = th.filter((v) => v !== INF);
    const highAgiThreshold = finite[finite.length - 1];
    const topRate = th[th.length - 1] === INF ? mainScale.rates[mainScale.rates.length - 2] : mainScale.rates[mainScale.rates.length - 1];
    let nySupp;
    if (agi > highAgiThreshold) {
      nySupp = nyTI * topRate - nyMain;
    } else if (s.in_effect) {
      const applicable = Math.max(0, agi - Math.max(prevThreshold, s.min_agi));
      const phaseIn = Math.min(1, applicable / s.phase_in_length);
      nySupp = single(s.recapture_base[sk], nyTI, false) + phaseIn * single(s.incremental_benefit[sk], nyTI, false);
    } else nySupp = 0;

    // Lever not in PolicyEngine: higher rates on the top brackets. ex.nyTop is
    // a list of {t, d}: the bracket starting at taxable income t pays d more
    // than today. New York's benefit recapture taxes ALL of a high earner's
    // income at the top bracket's rate once AGI is $50,000 past the bracket's
    // start (immediately above $25 million), so the increase is applied the
    // same way: d on the part of income in the bracket, plus d (phasing in
    // from the bracket below's increase) on the income beneath it.
    let nySurcharge = 0;
    const top = ex.nyTop || [];
    let b = -1;
    for (let i = 0; i < top.length; i++) if (nyTI >= top[i].t) b = i;
    if (b >= 0) {
      const tb = top[b].t, db = top[b].d, dprev = b > 0 ? top[b - 1].d : 0;
      const f = tb >= highAgiThreshold ? (agi > tb ? 1 : 0) : Math.min(1, Math.max(0, agi - tb) / s.phase_in_length);
      nySurcharge = db * (nyTI - tb) + (f * db + (1 - f) * dprev) * tb;
    }

    const nyBeforeCredits = nyMain + nySupp + nySurcharge; // ny_income_tax_before_credits

    // ny_household_credit (nonrefundable, first in order, capped by liability)
    const hc = ny.credits.household_credit;
    let hcPot;
    if (status === "SINGLE") hcPot = single(hc.single, agi, true);
    else hcPot = Math.max(single(hc.non_single.base, agi, true) + single(hc.non_single.additional, agi, true) * (people - 1), 0);
    const nyHousehold = Math.min(hcPot, Math.max(nyBeforeCredits, 0));
    const nyBeforeRefundable = Math.max(nyBeforeCredits - nyHousehold, 0);

    // ny_eitc: match of the federal credit, less the household credit
    const nyEitc = wftc ? 0 : Math.max(0, fedEitc * ny.credits.eitc.match - Math.min(nyBeforeCredits, nyHousehold));

    // ny_ctc_post_2024 (Empire State Child Credit, 2025-2027 rules)
    const ctc = ny.credits.ctc.post_2024;
    let escc = 0;
    if (wftc) {
      escc = 0;
    } else if (ctc.in_effect) {
      const perU4 = single(ctc.amount, 0, false), per4 = single(ctc.amount, 4, false), per17 = single(ctc.amount, 17, false);
      const base = (h.kidsUnder4 || 0) * perU4 + (h.kids4to16 || 0) * per4 + (h.kids17to18 || 0) * per17;
      if (base > 0) {
        const excess = Math.max(agi - ctc.phase_out.threshold[status], 0);
        const po = ctc.phase_out.rate > 0 ? Math.floor(excess / ctc.phase_out.increment) * ctc.phase_out.rate : 0;
        escc = Math.max(base - po, 0);
      }
    } else {
      // ny_ctc_pre_2024: the formula the credit returns to in 2028. The greater
      // of $100 per child under 17 (below the old federal phase-out start) or
      // 33% of the federal child credit figured with its 2017 parameters,
      // limited by 2026 federal income tax plus the refundable portion.
      const n = (h.kidsUnder4 || 0) + (h.kids4to16 || 0);
      if (n > 0) {
        const c17 = P.ctc2017, fb = P.fed.bracket;
        const fedTI = Math.max(0, wages - P.fed.standard[status]);
        let liab = 0, lo = 0;
        for (let i = 1; i <= 7; i++) {
          const hi = num(fb.thresholds[i][status]);
          if (fedTI > lo) liab += fb.rates[i] * (Math.min(fedTI, hi) - lo);
          lo = hi;
        }
        const ctcMax = n * single(c17.amount.base, 0, false);
        const po = Math.ceil(Math.max(0, agi - c17.phase_out.threshold[status]) / c17.phase_out.increment) * c17.phase_out.amount;
        const fedCtc = Math.max(0, ctcMax - po);
        const ph = c17.refundable.phase_in;
        let phaseIn = ph.rate * Math.max(0, wages - ph.threshold);
        if (n >= ph.min_children_for_ss_taxes_minus_eitc) phaseIn = Math.max(phaseIn, Math.max(0, 0.0765 * wages - fedEitc));
        const maxRef = Math.min(n * c17.refundable.individual_max, fedCtc);
        const refundable = Math.min(maxRef, Math.min(fedCtc, liab + phaseIn) - Math.min(fedCtc, liab));
        const claimed = Math.min(fedCtc, liab) + refundable;
        const cc = ny.credits.ctc.amount;
        const minimum = agi < c17.phase_out.threshold[status] ? cc.minimum * n : 0;
        escc = Math.max(minimum, claimed * cc.percent);
      }
    }
    let wftcCredit = 0;
    if (wftc) {
      const thr = h.married ? wftc.thrJoint : wftc.thrSingle;
      const red = Math.floor(Math.max(0, agi - thr) / 1000) * wftc.per1000;
      wftcCredit = Math.max(wftc.floor * kids, wftc.amount * kids - red);
    }
    const nyRefundable = nyEitc + escc + wftcCredit;
    const nyTax = nyBeforeRefundable - nyRefundable; // ny_income_tax

    // ---- New York City
    const nycTI = nyTI; // nyc_taxable_income
    const nycRegular = marginal(nyc.rates[sk], nycTI);
    const m = P.mamdani;
    // nyc_mamdani_income_tax. ex.fairShareAllIncome is the other reading of the
    // bill: the added rate on ALL city taxable income once it passes the threshold.
    let nycMamdani = m.in_effect ? marginal(m.rate, nycTI) : 0;
    if (m.in_effect && ex.fairShareAllIncome) nycMamdani = nycTI > m.rate.thresholds[1] ? m.rate.rates[1] * nycTI : 0;
    const nycBeforeCredits = nycRegular + nycMamdani;

    const nh = nyc.credits.household;
    const nycHousehold = status === "SINGLE" ? single(nh.flat_amount, agi, true) : single(nh.other_per_dependent, agi, true) * people;
    const nycBeforeRefundable = Math.max(nycBeforeCredits - nycHousehold, 0);

    // nyc_eitc
    const ne = nyc.credits.eitc;
    const pct0 = single(ne.percent, agi, false);
    const redThr = single(ne.reduction_threshold, agi, false);
    const pct = pct0 - (redThr > 0 ? ne.percent_reduction * Math.max(0, agi - redThr) : 0);
    const nycEitc = fedEitc * pct;

    // nyc_school_tax_credit
    const sc = nyc.credits.school;
    const fixed = agi <= sc.fixed.income_limit ? sc.fixed.amount[status] : 0;
    const rr = sc.rate_reduction, ra = rr.amount;
    let rate = 0;
    if (agi <= rr.income_limit && nycTI <= rr.taxable_income_limit) {
      const t = ra.threshold[status];
      rate = nycTI > t ? ra.base[status] + ra.excess_rate * (nycTI - t) : ra.first_band_rate * nycTI;
    }
    const nycSchool = fixed + rate;

    // nyc_income_tax_elimination_credit
    const el = nyc.credits.income_tax_elimination;
    let nycElim = 0;
    if (el.in_effect && kids > 0) {
      const thr = single(el.income_threshold[sk], kids, false) + (ex.elimThresholdBoost || 0);
      if (agi <= thr + el.phase_out_width) {
        const excess = Math.max(agi - thr, 0);
        const frac = Math.round((Math.max(el.phase_out_width - excess, 0) / el.phase_out_width) * 1e4) / 1e4;
        nycElim = Math.max(nycBeforeRefundable - nycEitc, 0) * frac;
      }
    }

    const nycRefundable = nycEitc + nycSchool + nycElim;
    const nycTax = nycBeforeRefundable - nycRefundable; // nyc_income_tax

    return {
      status, agi, fedEitc,
      ny: { taxable: nyTI, main: nyMain, supplemental: nySupp, surcharge: nySurcharge, beforeCredits: nyBeforeCredits,
            householdCredit: nyHousehold, eitc: nyEitc, escc, wftc: wftcCredit, tax: nyTax },
      nyc: { taxable: nycTI, regular: nycRegular, mamdani: nycMamdani, beforeCredits: nycBeforeCredits,
             householdCredit: nycHousehold, eitc: nycEitc, school: nycSchool, elimination: nycElim, tax: nycTax },
      total: nyTax + nycTax,
    };
  }

  const api = { compute, marginal, single };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.NYTax = api;
})(typeof self !== "undefined" ? self : this);
